import { Component, Element, Event, EventEmitter, h, Host, Prop, Watch } from '@stencil/core';
import { CLOSE_BUTTON_LABEL } from '../../a11y';
import { BannerSeverity } from '../../types';
import { handleAutofocus } from '../../utils/autofocus';

/**
 @slot headline - named slot 'headline', optional, made for text, but HTML works as well.
 @slot content - named slot 'content', optional, made for text, but HTML works as well.
 */
@Component({
  tag: 'groupui-banner',
  styleUrl: 'banner.scss',
  shadow: true,
})
export class Banner {
  /**
   * Severity of the banner
   */
  @Prop({ reflect: true }) readonly severity: BannerSeverity = 'information';

  /**
   * Hides severity icon
   */
  @Prop({ reflect: true }) readonly hideIcon: boolean = false;

  /**
   * Hides the close button that dismisses the banner
   */
  @Prop({ reflect: true }) readonly hideCloseButton: boolean = false;

  /**
   * Hides banner after given amount of milliseconds and emits groupuiClose event.
   */
  @Prop({ reflect: true }) readonly autoDismiss: number;

  /**
   * Determines if the banner is visible or not.
   */
  @Prop({ reflect: true, mutable: true }) visible: boolean = false;

  /**
   * Is dispatched when the banner is closed through click and/or autoDismiss.
   *
   * Hint: The banner itself just sets its CSS display value to 'none'.
   * Use this event to e.g. remove element from the DOM inside your application.
   */
  @Event({ bubbles: false }) groupuiClose: EventEmitter<void>;

  /**
   * Dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * sets a custom accessible text for the close button
   */
  @Prop({ reflect: true, attribute: 'a11y-label-close-button' }) readonly a11yLabelCloseButton: string;

  /**
   * sets a custom accessible text for the severity icon (by default, it is hidden)
   */
  @Prop({ reflect: true, attribute: 'a11y-label-severity-icon' }) readonly a11yLabelSeverityIcon: string;

  @Element() host: HTMLElement;

  private timeoutId: ReturnType<typeof setTimeout>;

  componentWillLoad() {
    // the "display" property is controlled via JS in this component to enable animating it
    this.host.style.display = this.visible ? 'block' : 'none';

    // the animation-duration is set to 0s initially to prevent the animation from being played on first render
    this.host.style.animationDuration = '0s';

    // set "display: none" not before the hide animation is finished
    this.host.addEventListener('animationend', () => {
      if (!this.visible) {
        this.host.style.display = 'none';
      }
    });
  }

  componentDidLoad() {
    if (this.visible && this.autoDismiss) {
      this.initiateAutoDismiss();
    }
    this.groupuiDidLoad.emit();
    handleAutofocus(this.host);
  }

  @Watch('visible')
  onVisibleChanged() {
    if (this.visible) {
      this.host.style.display = 'block';
    }
    this.removeInitialAnimationDurationOverride();
    this.handleVisibilityAndDismissal();
  }

  @Watch('autoDismiss')
  onAutoDismissChanged() {
    if (this.autoDismiss) {
      this.initiateAutoDismiss();
    } else {
      this.clearTimeoutIfExist();
    }
  }

  private removeInitialAnimationDurationOverride() {
    this.host.style.removeProperty('animation-duration');
  }

  private handleVisibilityAndDismissal() {
    if (!this.visible) {
      this.clearTimeoutIfExist();
      setTimeout(() => this.groupuiClose.emit(), this.getFadeoutDuration());
      return;
    }

    if (this.autoDismiss) {
      this.initiateAutoDismiss();
    }
  }

  private getFadeoutDuration(): number {
    const cssDuration = getComputedStyle(this.host)
      .getPropertyValue('--groupui-sys-duration-medium-2')
      .replace('s', '');
    return Number(cssDuration) * 1000;
  }

  private clearTimeoutIfExist() {
    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
      this.timeoutId = undefined;
    }
  }

  private initiateAutoDismiss() {
    this.clearTimeoutIfExist();
    this.timeoutId = setTimeout(() => {
      this.visible = false;
      this.timeoutId = undefined;
    }, this.autoDismiss);
  }

  private isHeadlineSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="headline"]');
  }

  private isContentSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="content"]');
  }

  disconnectedCallback() {
    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
    }
  }

  render() {
    let ariaProps: { 'aria-label'?: string; 'aria-hidden'?: string };
    if (this.a11yLabelSeverityIcon) {
      ariaProps = { 'aria-label': this.a11yLabelSeverityIcon };
    } else {
      ariaProps = { 'aria-hidden': 'true' };
    }

    return (
      <Host>
        <div
          role="alert"
          class={{ 'has-headline': this.isHeadlineSlotProvided(), 'has-content': this.isContentSlotProvided() }}
        >
          {!this.hideIcon && !['success', 'warning', 'danger'].includes(this.severity) && (
            <groupui-icon id="icon" name="info-filled-24" {...ariaProps} />
          )}
          {!this.hideIcon && this.severity === 'success' && (
            <groupui-icon id="icon" name="success-filled-24" {...ariaProps} />
          )}
          {!this.hideIcon && this.severity === 'warning' && (
            <groupui-icon id="icon" name="warning-filled-24" {...ariaProps} />
          )}
          {!this.hideIcon && this.severity === 'danger' && (
            <groupui-icon id="icon" name="error-filled-24" {...ariaProps} />
          )}
          {this.isHeadlineSlotProvided() && <slot name="headline" />}
          {this.isContentSlotProvided() && <slot name="content" />}
          {!this.hideCloseButton && (
            <groupui-icon-button
              id="close"
              icon="close-16"
              variant="weak"
              onClick={this.handleClose}
              onKeyDown={this.handleKeyDown}
              aria-label={this.a11yLabelCloseButton || CLOSE_BUTTON_LABEL}
            ></groupui-icon-button>
          )}
        </div>
      </Host>
    );
  }

  private handleClose = () => {
    this.visible = false;
  };

  private handleKeyDown = (event: KeyboardEvent) => {
    if (event.code === 'Enter' || event.code === 'Space') {
      this.visible = false;
    }
  };
}
